<?php
fscanf(STDIN, "%d %d", $n, $t);

// dp[y][lastDir][peaks][valleys] = count
// lastDir: 0 = none (only for first step), 1 = up, 2 = down
$dp = array();
for ($y = 1; $y <= 4; $y++) {
    $dp[$y][0][0][0] = 1;
}

for ($i = 2; $i <= $n; $i++) {
    $ndp = array();
    for ($y = 1; $y <= 4; $y++) {
        if (!isset($dp[$y])) continue;
        foreach ($dp[$y] as $lastDir => $peaksArr) {
            foreach ($peaksArr as $peaks => $valleysArr) {
                foreach ($valleysArr as $valleys => $cnt) {
                    for ($ny = 1; $ny <= 4; $ny++) {
                        if ($ny == $y) continue;
                        $newDir = ($ny > $y) ? 1 : 2;
                        $npeaks = $peaks;
                        $nvalleys = $valleys;
                        if ($lastDir != 0) {
                            if ($lastDir == 1 && $newDir == 2) {
                                $npeaks++;
                            } elseif ($lastDir == 2 && $newDir == 1) {
                                $nvalleys++;
                            }
                        }
                        if ($npeaks > $t) continue;
                        if ($nvalleys > $t) continue;
                        if (!isset($ndp[$ny][$newDir][$npeaks][$nvalleys])) {
                            $ndp[$ny][$newDir][$npeaks][$nvalleys] = 0;
                        }
                        $ndp[$ny][$newDir][$npeaks][$nvalleys] += $cnt;
                    }
                }
            }
        }
    }
    $dp = $ndp;
}

$total = 0;
for ($y = 1; $y <= 4; $y++) {
    if (!isset($dp[$y])) continue;
    foreach ($dp[$y] as $lastDir => $peaksArr) {
        foreach ($peaksArr as $peaks => $valleysArr) {
            foreach ($valleysArr as $valleys => $cnt) {
                if ($peaks == $t && $valleys == $t - 1) {
                    $total += $cnt;
                }
            }
        }
    }
}

echo $total . "\n";
